  `article_section_no` varchar(255) DEFAULT NULL,
  `title` text,
  `description` longtext,
  `part_chapter` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=154 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
